    "private": true,
    "engines": {
        "node": ">=26"
    },
    "version": "0.0.0",
    "type": "module",
    "dependencies": {
        "automerge": "^1.0.1-preview.7",
        "bcrypt": "^6.0.0",
        "cors": "^2.8.6",
        "dotenv": "^18.0.4",
        "express": "^5.2.1",
        "jsonwebtoken": "^9.0.3",
        "ley": "^0.8.1",
        "postgres": "^3.4.9",
        "ws": "^8.21.3"
    },
    "scripts": {
        "test": "vitest run",
        "generate-jwt-secret": "node cli/generate-jwt-secret.js",
        "import-legacy-documents": "node cli/import-legacy-documents.js",
        "make:migration": "ley new",
        "migrate": "ley up"
    },
