// Starts the API and its database in Docker for the end-to-end tests and stops them after.
import { execFileSync } from 'child_process'
import { fileURLToPath } from 'url'
import { dirname, resolve } from 'path'

const composeFile = resolve(dirname(fileURLToPath(import.meta.url)), '../../../docker-compose.test.yml')
const compose = (...args) => execFileSync('docker', ['compose', '-f', composeFile, ...args], { stdio: 'inherit' })

export default function({ provide }) {
    compose('up', '--build', '--wait', '--quiet-pull')
    provide('apiUrl', 'http://localhost:16943')
    provide('websocketUrl', 'ws://localhost:16943')

    return () => compose('down', '--volumes')
}

import { defineConfig } from 'vitest/config'

// The tests need a Postgres database, pointed at by the usual PG* environment variables,
// with the migrations applied (npx ley up). They create their own users and remove them.
export default defineConfig({
    test: {
        environment: 'node',
        fileParallelism: false
    }
})

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { pull, push, encrypt, validateRows, validateEncryptedRows, shutdown } from '../sync.js'
import { findUserById } from '../db.js'
import { createTestUser, deleteTestUser, category, note } from './helpers.js'
import sql from '../sql.js'

let userId

beforeAll(async() => {
    userId = await createTestUser('sync')
})

afterAll(async() => {
    shutdown()
    await deleteTestUser(userId)
    await sql.end()
})

const ids = rows => rows.map(row => row.id)

describe('push and pull', () => {
    it('starts empty at seq 0', async() => {
        expect(await pull(userId, 0)).toEqual({ seq: 0, more: false, encrypted: false, categories: [], notes: [] })
    })

    it('accepts new rows at version 0 and numbers each write', async() => {
        const result = await push(userId, { categories: [category('c1')], notes: [note('n1'), note('n2')] })

        expect(result.seq).toBe(3)
        expect(result.accepted).toEqual({ categories: [{ id: 'c1', version: 1, seq: 1 }], notes: [{ id: 'n1', version: 1, seq: 2 }, { id: 'n2', version: 1, seq: 3 }] })
        expect(result.rejected).toEqual({ categories: [], notes: [] })

        const pulled = await pull(userId, 0)
        expect(pulled.seq).toBe(3)
        expect(pulled.categories).toEqual([{ ...category('c1'), version: 1, seq: 1 }])
        expect(pulled.notes).toEqual([{ ...note('n1'), version: 1, seq: 2 }, { ...note('n2'), version: 1, seq: 3 }])
    })

    it('returns only rows written after since', async() => {
        const pulled = await pull(userId, 2)
        expect(ids(pulled.categories)).toEqual([])
        expect(ids(pulled.notes)).toEqual(['n2'])
        expect((await pull(userId, 3)).notes).toEqual([])
    })

    it('accepts an edit based on the current version and moves the row to the end', async() => {
        const result = await push(userId, { notes: [note('n1', { title: 'edited', version: 1 })] })
        expect(result.accepted.notes).toEqual([{ id: 'n1', version: 2, seq: 4 }])

        const pulled = await pull(userId, 3)
        expect(pulled.notes).toEqual([{ ...note('n1'), title: 'edited', version: 2, seq: 4 }])
    })

    it('rejects an edit based on an old version and hands back the current row', async() => {
        const result = await push(userId, { notes: [note('n1', { title: 'stale', version: 1 })] })
        expect(result.accepted.notes).toEqual([])
        expect(result.rejected.notes).toEqual([{ ...note('n1'), title: 'edited', version: 2, seq: 4 }])
        expect(result.seq).toBe(4)
        expect((await pull(userId, 4)).notes).toEqual([])
    })

    it('answers a row it never had, pushed as if it had, with an empty tombstone to build on', async() => {
        const result = await push(userId, { notes: [note('never', { version: 3 })], categories: [category('never', { version: 1 })] })
        expect(result.rejected.notes).toEqual([{ id: 'never', categoryId: null, title: '', content: '', created: '', modified: '', version: 0, seq: 0, deleted: true }])
        expect(result.rejected.categories[0]).toMatchObject({ id: 'never', version: 0, deleted: true })
        expect(result.seq).toBe(4)
    })

    it('rejects a second creation of an id the server already has', async() => {
        const result = await push(userId, { notes: [note('n1')] })
        expect(result.rejected.notes[0]).toMatchObject({ id: 'n1', version: 2 })
    })

    it('keeps a deleted row as a tombstone that later pulls see', async() => {
        const result = await push(userId, { notes: [note('n2', { title: '', content: '', version: 1, deleted: true })] })
        expect(result.accepted.notes).toEqual([{ id: 'n2', version: 2, seq: 5 }])

        const pulled = await pull(userId, 4)
        expect(pulled.notes).toEqual([{ ...note('n2'), title: '', content: '', version: 2, seq: 5, deleted: true }])
    })

    it('rejects an edit of a row that was deleted meanwhile with the tombstone', async() => {
        const result = await push(userId, { notes: [note('n2', { title: 'still typing', version: 1 })] })
        expect(result.rejected.notes[0]).toMatchObject({ id: 'n2', deleted: true, version: 2 })

        // the device brings it back by building on the tombstone
        const again = await push(userId, { notes: [note('n2', { title: 'still typing', version: 2 })] })
        expect(again.accepted.notes).toEqual([{ id: 'n2', version: 3, seq: 6 }])
        expect((await pull(userId, 5)).notes[0]).toMatchObject({ id: 'n2', title: 'still typing', deleted: false })
    })

    it('handles accepted and rejected rows in one push', async() => {
        const result = await push(userId, { categories: [category('c1', { name: 'renamed', version: 1 }), category('c2')], notes: [note('n1', { version: 0 })] })
        expect(ids(result.accepted.categories)).toEqual(['c1', 'c2'])
        expect(ids(result.rejected.notes)).toEqual(['n1'])
        expect(result.seq).toBe(8)
    })

    it('gives two pushes at the same moment their own seq numbers', async() => {
        const rows = Array.from({ length: 20 }, (_, index) => note(`burst-${index}`))
        const [a, b] = await Promise.all([
            push(userId, { notes: rows.slice(0, 10) }),
            push(userId, { notes: rows.slice(10) })
        ])
        const seqs = [...a.accepted.notes, ...b.accepted.notes].map(row => row.seq).sort((x, y) => x - y)
        expect(seqs).toEqual(Array.from({ length: 20 }, (_, index) => 9 + index))
        expect(Math.max(a.seq, b.seq)).toBe(28)
    })

    it('pages a long pull and says where to continue', async() => {
        const first = await pull(userId, 0, 10)
        expect(first.more).toBe(true)
        expect(first.notes.length).toBe(10)
        expect(first.seq).toBe(first.notes[9].seq)
        // categories beyond the page come with the next page instead
        expect(first.categories.every(row => row.seq <= first.seq)).toBe(true)

        const seen = [...first.notes]
        let { seq, more } = first
        while(more) {
            const page = await pull(userId, seq, 10)
            seen.push(...page.notes)
            ;({ seq, more } = page)
        }
        expect(seq).toBe(28)
        expect(new Set(ids(seen)).size).toBe(22)
    })
})

describe('validateRows', () => {
    it('accepts the wire shape and refuses anything else', () => {
        expect(validateRows({ categories: [category('c')], notes: [note('n'), note('m', { categoryId: 'c' })] })).toBe(true)
        expect(validateRows({})).toBe(true)
        expect(validateRows({ notes: [note('n', { version: -1 })] })).toBe(false)
        expect(validateRows({ notes: [note('n', { version: '1' })] })).toBe(false)
        expect(validateRows({ notes: [note('n', { deleted: 'yes' })] })).toBe(false)
        expect(validateRows({ notes: [note('n', { title: null })] })).toBe(false)
        expect(validateRows({ notes: [note('n', { categoryId: 5 })] })).toBe(false)
        expect(validateRows({ notes: [note('')] })).toBe(false)
        expect(validateRows({ notes: 'n' })).toBe(false)
        expect(validateRows({ categories: [{ id: 'c' }] })).toBe(false)
    })

    it('accepts only the encrypted fields with id and version for the switch to encryption', () => {
        expect(validateEncryptedRows({ categories: [{ id: 'c', version: 1, name: 'x' }], notes: [{ id: 'n', version: 2, title: 'x', content: 'y' }] })).toBe(true)
        expect(validateEncryptedRows({ notes: [{ id: 'n', version: 2, title: 'x' }] })).toBe(false)
        expect(validateEncryptedRows({ notes: [{ id: 'n', version: -1, title: 'x', content: 'y' }] })).toBe(false)
        expect(validateEncryptedRows({ categories: [{ id: 'c', version: 1 }] })).toBe(false)
    })
})

describe('encrypt', () => {
    const encryption = { salt: 's', wrappedKey: 'w', recoverySalt: 'rs', recoveryWrappedKey: 'rw', recoveryPassword: 'rp' }
    let encryptedUserId

    beforeAll(async() => {
        encryptedUserId = await createTestUser('sync-encrypt')
        await push(encryptedUserId, { categories: [category('c1')], notes: [note('n1'), note('n2'), note('gone')] })
        await push(encryptedUserId, { notes: [note('gone', { title: '', content: '', version: 1, deleted: true })] })
    })

    afterAll(() => deleteTestUser(encryptedUserId))

    const live = async() => {
        const { categories, notes } = await pull(encryptedUserId, 0)
        return { categories: categories.filter(row => !row.deleted), notes: notes.filter(row => !row.deleted) }
    }

    it('refuses when the device does not hold every live row at its current version', async() => {
        const { categories, notes } = await live()
        await expect(encrypt(encryptedUserId, { password: 'p', encryption, categories, notes: notes.slice(1) })).rejects.toThrow('Out of date')
        await expect(encrypt(encryptedUserId, { password: 'p', encryption, categories, notes: notes.map(row => ({ ...row, version: 0 })) })).rejects.toThrow('Out of date')
        expect((await findUserById(encryptedUserId)).encrypted).toBe(false)
        expect((await live()).notes[0].title).toBe('title n1')
    })

    it('replaces every live row with its encrypted form and turns the account on in one step', async() => {
        const { categories, notes } = await live()
        const before = (await pull(encryptedUserId, 0)).seq
        const result = await encrypt(encryptedUserId, {
            password: '[REDACTED]',
            encryption,
            categories: categories.map(row => ({ ...row, name: `enc:${row.name}` })),
            notes: notes.map(row => ({ ...row, title: `enc:${row.title}`, content: `enc:${row.content}` }))
        })
        expect(result.seq).toBe(before + 3)

        const user = await findUserById(encryptedUserId)
        expect(user.encrypted).toBe(true)
        expect(user.password).toBe('hashed-auth-key')
        expect(user.salt).toBe('s')
        expect(user.recovery_password).toBe('rp')

        // every live row is a new version, so other devices pull it again
        const pulled = await pull(encryptedUserId, before)
        expect(pulled.encrypted).toBe(true)
        expect(pulled.categories).toEqual([expect.objectContaining({ id: 'c1', name: 'enc:name c1', version: 2 })])
        expect(pulled.notes.map(row => [row.id, row.title, row.version])).toEqual([['n1', 'enc:title n1', 2], ['n2', 'enc:title n2', 2]])
    })

    it('cannot be done twice', async() => {
        const { categories, notes } = await live()
        await expect(encrypt(encryptedUserId, { password: 'p', encryption, categories, notes })).rejects.toThrow('Already encrypted')
    })
})

// The HTTP API and the websocket as a device uses them, on a real server.
import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import WebSocket from 'ws'
import { findUserByEmail } from '../db.js'
import { shutdown } from '../sync.js'
import { startServer, note, category, until } from './helpers.js'
import sql from '../sql.js'

let server
let emails = []
let sockets = []

const email = label => {
    const address = `routes-${label}-${Date.now()}-${Math.random().toString(36).slice(2)}@test.invalid`
    emails.push(address)
    return address
}

async function call(path, { token, ...body } = {}, method = 'POST') {
    const response = await fetch(`${server.url}${path}`, {
        method,
        headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
        body: method === 'GET' ? undefined : JSON.stringify(body)
    })
    const text = await response.text()
    return { status: response.status, body: response.headers.get('content-type')?.includes('json') ? JSON.parse(text) : text }
}

function listen(token) {
    const ws = new WebSocket(`${server.websocketUrl}?token=${token}`)
    const messages = []
    ws.on('message', data => messages.push(JSON.parse(data)))
    sockets.push(ws)
    return new Promise((resolve, reject) => {
        ws.on('open', () => resolve(messages))
        ws.on('error', reject)
    })
}

const encryption = { salt: 'salt', wrappedKey: 'wrapped', recoverySalt: 'recovery-salt', recoveryWrappedKey: 'recovery-wrapped', recoveryPassword: '[REDACTED]' }

beforeAll(async() => {
    server = await startServer()
})

afterAll(async() => {
    for(const ws of sockets) {
        ws.terminate()
    }
    shutdown()
    await server.close()
    for(const address of emails) {
        await sql`delete from users where email = ${address}`
    }
    await sql.end()
})

describe('accounts without encryption', () => {
    const address = email('plain')
    let token

    it('registers and logs in with the password itself', async() => {
        const registered = await call('/register', { email: address, password: 'password' })
        expect(registered.status).toBe(200)
        expect(registered.body).toMatchObject({ encrypted: false, wrappedKey: null })

        expect((await call('/salt', { email: address })).body).toEqual({ encrypted: false, salt: null })

        const login = await call('/login', { email: address, password: 'password' })
        expect(login.status).toBe(200)
        expect(login.body).toMatchObject({ encrypted: false, wrappedKey: null })
        token = [REDACTED]

        expect((await call('/login', { email: address, password: 'wrong' })).status).toBe(400)
        expect((await call('/register', { email: address, password: 'password' })).body).toBe('Email already registered')
    })

    it('changes the password', async() => {
        expect((await call('/change-password', { token, currentPassword: 'wrong', newPassword: 'new' })).status).toBe(400)
        expect((await call('/change-password', { token, currentPassword: 'password', newPassword: 'new' })).status).toBe(200)
        expect((await call('/login', { email: address, password: 'new' })).status).toBe(200)
    })

    it('has no recovery phrase and cannot be given one', async() => {
        expect((await call('/recovery', { email: address })).status).toBe(400)
        expect((await call('/recovery-phrase', { token, recoverySalt: 'rs', recoveryWrappedKey: 'rw', recoveryPassword: 'ra' })).status).toBe(400)
    })
})

describe('accounts with encryption', () => {
    const address = email('encrypted')
    let token

    it('registers with the derived key and the wrapped data key, and hands the wrapped key back at login', async() => {
        expect((await call('/register', { email: address, password: 'auth-key', encryption: { salt: 'only' } })).status).toBe(400)

        const registered = await call('/register', { email: address, password: 'auth-key', encryption })
        expect(registered.status).toBe(200)
        expect(registered.body).toMatchObject({ encrypted: true, wrappedKey: 'wrapped' })

        expect((await call('/salt', { email: address })).body).toEqual({ encrypted: true, salt: 'salt' })

        const login = await call('/login', { email: address, password: 'auth-key' })
        expect(login.body).toMatchObject({ encrypted: true, wrappedKey: 'wrapped' })
        token = [REDACTED]

        // the server holds hashes, never the keys themselves
        const user = await findUserByEmail(address)
        expect(user.password).not.toBe('auth-key')
        expect(user.recovery_password).not.toBe('recovery-auth')
    })

    it('changes the password only together with the key wrapped under the new one', async() => {
        expect((await call('/change-password', { token, currentPassword: 'auth-key', newPassword: 'auth-key-2' })).status).toBe(400)
        expect((await call('/change-password', { token, currentPassword: 'auth-key', newPassword: 'auth-key-2', encryption: { salt: 'salt-2', wrappedKey: 'wrapped-2' } })).status).toBe(200)

        expect((await call('/salt', { email: address })).body).toEqual({ encrypted: true, salt: 'salt-2' })
        expect((await call('/login', { email: address, password: 'auth-key-2' })).body).toMatchObject({ wrappedKey: 'wrapped-2' })
    })

    it('resets a forgotten password with the recovery phrase', async() => {
        expect((await call('/recovery', { email: address })).body).toEqual({ recoverySalt: 'recovery-salt', recoveryWrappedKey: 'recovery-wrapped' })

        const wrong = await call('/reset-password', { email: address, recoveryPassword: 'wrong', password: 'auth-key-3', encryption: { salt: 'salt-3', wrappedKey: 'wrapped-3' } })
        expect(wrong.status).toBe(400)
        expect((await call('/login', { email: address, password: 'auth-key-2' })).status).toBe(200)

        const reset = await call('/reset-password', { email: address, recoveryPassword: '[REDACTED]', password: 'auth-key-3', encryption: { salt: 'salt-3', wrappedKey: 'wrapped-3' } })
        expect(reset.status).toBe(200)
        expect((await call('/login', { email: address, password: 'auth-key-3' })).body).toMatchObject({ wrappedKey: 'wrapped-3' })
        // the phrase stays valid
        expect((await call('/recovery', { email: address })).body.recoverySalt).toBe('recovery-salt')
    })

    it('replaces the recovery phrase', async() => {
        expect((await call('/recovery-phrase', { token, recoverySalt: 'rs-2', recoveryWrappedKey: 'rw-2', recoveryPassword: 'ra-2' })).status).toBe(200)
        expect((await call('/recovery', { email: address })).body).toEqual({ recoverySalt: 'rs-2', recoveryWrappedKey: 'rw-2' })
        expect((await call('/reset-password', { email: address, recoveryPassword: '[REDACTED]', password: 'x', encryption: { salt: 's', wrappedKey: 'w' } })).status).toBe(400)
        expect((await call('/reset-password', { email: address, recoveryPassword: 'ra-2', password: 'auth-key-4', encryption: { salt: 's4', wrappedKey: 'w4' } })).status).toBe(200)
    })
})

describe('changes', () => {
    let token
    let messages

    beforeAll(async() => {
        ;({ body: { token } } = await call('/register', { email: email('changes'), password: 'password' }))
        messages = await listen(token)
    })

    it('needs a token', async() => {
        expect((await call('/changes?since=0', {}, 'GET')).status).toBe(401)
        expect((await call('/changes', { notes: [] })).status).toBe(401)
    })

    it('pushes, pulls and nudges the websocket with the new seq', async() => {
        const pushed = await call('/changes', { token, categories: [category('c1')], notes: [note('n1')] })
        expect(pushed.status).toBe(200)
        expect(pushed.body.accepted.notes).toEqual([{ id: 'n1', version: 1, seq: 2 }])

        await until(() => messages.length > 0, 'the websocket nudge')
        expect(messages).toEqual([{ seq: 2 }])

        const pulled = await call('/changes?since=0', { token }, 'GET')
        expect(pulled.body).toMatchObject({ seq: 2, more: false, encrypted: false })
        expect(pulled.body.notes[0]).toMatchObject({ id: 'n1', version: 1 })
        expect((await call('/changes?since=2', { token }, 'GET')).body.notes).toEqual([])
    })

    it('refuses rows in the wrong shape and a bad since', async() => {
        expect((await call('/changes', { token, notes: [{ id: 'x' }] })).status).toBe(400)
        expect((await call('/changes?since=-1', { token }, 'GET')).status).toBe(400)
        expect((await call('/changes?since=abc', { token }, 'GET')).status).toBe(400)
    })

    it('turns an account on to encryption, refusing while the device is behind', async() => {
        const rows = { categories: [category('c1', { name: 'enc', version: 1 })], notes: [note('n1', { title: 'enc', content: 'enc', version: 1 })] }
        const behind = await call('/encrypt', { token, password: 'auth-key', encryption, categories: rows.categories, notes: [] })
        expect(behind.status).toBe(409)

        const done = await call('/encrypt', { token, password: 'auth-key', encryption, ...rows })
        expect(done.status).toBe(200)
        expect(done.body).toEqual({ seq: 4 })
        await until(() => messages.some(message => message.seq === 4), 'the nudge for the rewrite')

        expect((await call('/login', { email: emails.at(-1), password: 'auth-key' })).body).toMatchObject({ encrypted: true, wrappedKey: 'wrapped' })
        expect((await call('/login', { email: emails.at(-1), password: 'password' })).status).toBe(400)
        const pulled = await call('/changes?since=2', { token }, 'GET')
        expect(pulled.body.encrypted).toBe(true)
        expect(pulled.body.notes[0]).toMatchObject({ id: 'n1', title: 'enc', version: 2 })
    })

    it('rejects a websocket without a valid token', async() => {
        const ws = new WebSocket(`${server.websocketUrl}?token=nope`)
        sockets.push(ws)
        await new Promise(resolve => ws.on('error', resolve))
    })
})

import { describe, it, expect } from 'vitest'
import { readLegacyDocument } from '../legacy.js'
import { legacyDocumentBytes, legacyDocumentContents } from './fixtures/legacy-document.js'

describe('readLegacyDocument', () => {
    it('reads a document saved by the automerge 1.0.1-preview.7 build as plain values', () => {
        expect(readLegacyDocument(legacyDocumentBytes)).toEqual(legacyDocumentContents)
    })
})

import sql from '../sql.js'
import { createUser } from '../db.js'
import { createServer } from '../server.js'

// a throwaway user for one test file, deleting it cascades to every row it owns
export async function createTestUser(label) {
    const user = await createUser(`${label}-${Date.now()}-${Math.random().toString(36).slice(2)}@test.invalid`, 'password')
    return user.id
}

export async function deleteTestUser(userId) {
    await sql`delete from users where id = ${userId}`
}

export async function seedLegacyDocument(userId, bytes) {
    await sql`insert into user_store(user_id, key, value) values(${userId}, 'automergeDoc', ${Buffer.from(bytes)})`
}

export const category = (id, extra = {}) => ({ id, name: `name ${id}`, created: '2024-01-01T00:00:00.000Z', modified: '2024-01-01T00:00:00.000Z', version: 0, deleted: false, ...extra })
export const note = (id, extra = {}) => ({ id, categoryId: null, title: `title ${id}`, content: `content ${id}`, created: '2024-01-01T00:00:00.000Z', modified: '2024-01-01T00:00:00.000Z', version: 0, deleted: false, ...extra })

// the real HTTP and websocket server on a free port
export async function startServer() {
    const server = createServer()
    await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
    const { port } = server.address()
    return {
        url: `http://127.0.0.1:${port}`,
        websocketUrl: `ws://127.0.0.1:${port}`,
        close: () => new Promise(resolve => server.close(resolve))
    }
}

export async function until(condition, what = 'condition') {
    for(let attempt = 0; attempt < 500 && !condition(); attempt++) {
        await new Promise(resolve => setTimeout(resolve, 10))
    }
    if(!condition()) {
        throw new Error(`timed out waiting for ${what}`)
    }
}

import { describe, it, expect, afterAll } from 'vitest'
import { importLegacyDocument } from '../migrate.js'
import { pull, push, shutdown } from '../sync.js'
import { findUserById } from '../db.js'
import { createTestUser, deleteTestUser, seedLegacyDocument, note } from './helpers.js'
import { legacyDocumentBytes, legacyDocumentContents } from './fixtures/legacy-document.js'
import sql from '../sql.js'

let userIds = []

async function user(label, seed = true) {
    const id = await createTestUser(label)
    userIds.push(id)
    if(seed) {
        await seedLegacyDocument(id, legacyDocumentBytes)
    }
    return findUserById(id)
}

